import pathlib
FILES = {
    'server/config.py': '"""Env-driven config."""\nimport os, secrets\nfrom pathlib import Path\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nBRIDGE_HOST = os.getenv("BRIDGE_HOST", "0.0.0.0")\nBRIDGE_PORT = int(os.getenv("BRIDGE_PORT", "8787"))\n\nOBS_WS_HOST = os.getenv("OBS_WS_HOST", "127.0.0.1")\nOBS_WS_PORT = int(os.getenv("OBS_WS_PORT", "4455"))\nOBS_WS_PASSWORD = os.getenv("OBS_WS_PASSWORD", "")\n\nSTREAM_WIDTH = int(os.getenv("STREAM_WIDTH", "1920"))\nSTREAM_HEIGHT = int(os.getenv("STREAM_HEIGHT", "1080"))\n\nTWELVE_DATA_API_KEY = os.getenv("TWELVE_DATA_API_KEY", "")\nBINANCE_WS_URL = os.getenv("BINANCE_WS_URL", "")\n\nCONTROL_TOKEN = os.getenv("CONTROL_TOKEN") or secrets.token_urlsafe(12)\n\nCORE_DIR = Path(__file__).resolve().parent.parent / "core"\nMOCK_MARKET = not TWELVE_DATA_API_KEY\n',
    'server/hub.py': '"""OBS control hub. All OBS WebSocket traffic goes through here."""\nimport threading, logging\nfrom obswebsocket import obsws, requests\nfrom server.config import OBS_WS_HOST, OBS_WS_PORT, OBS_WS_PASSWORD\nfrom automation.layouts import LAYOUTS\n\nlog = logging.getLogger(__name__)\nLIVE = "03-live"\nCAM_SOURCES = [f"CAM-{i}" for i in range(1, 6)]\n\n\nclass Hub:\n    def __init__(self):\n        self._ws = None\n        self._lock = threading.Lock()\n\n    @property\n    def connected(self):\n        return self._ws is not None\n\n    def connect(self):\n        with self._lock:\n            if self._ws:\n                return True\n            try:\n                ws = obsws(OBS_WS_HOST, OBS_WS_PORT, OBS_WS_PASSWORD)\n                ws.connect()\n                self._ws = ws\n                log.info("OBS hub connected @ %s:%s", OBS_WS_HOST, OBS_WS_PORT)\n                return True\n            except Exception as e:\n                log.warning("OBS hub connect failed: %s", e)\n                self._ws = None\n                return False\n\n    def disconnect(self):\n        with self._lock:\n            if self._ws:\n                try:\n                    self._ws.disconnect()\n                except Exception:\n                    pass\n                self._ws = None\n\n    def _call(self, req):\n        with self._lock:\n            if not self._ws:\n                raise RuntimeError("OBS not connected")\n            return self._ws.call(req)\n\n    def canvas(self):\n        vs = self._call(requests.GetVideoSettings())\n        return {"w": vs.getBaseWidth(), "h": vs.getBaseHeight()}\n\n    def scenes(self):\n        return [s["sceneName"] for s in self._call(requests.GetSceneList()).getScenes()]\n\n    def current_scene(self):\n        return self._call(requests.GetSceneList()).getCurrentProgramSceneName()\n\n    def items(self, scene=LIVE):\n        out = []\n        for it in self._call(requests.GetSceneItemList(sceneName=scene)).getSceneItems():\n            tr = it.get("sceneItemTransform", {})\n            bw, bh = tr.get("boundsWidth", 0), tr.get("boundsHeight", 0)\n            out.append({\n                "name": it["sourceName"],\n                "id": it["sceneItemId"],\n                "x": tr.get("positionX", 0), "y": tr.get("positionY", 0),\n                "w": bw or tr.get("sourceWidth", 0), "h": bh or tr.get("sourceHeight", 0),\n                "visible": it.get("sceneItemEnabled", True),\n            })\n        return out\n\n    def audio_level(self, input_name):\n        lv = self._call(requests.GetInputAudioLevels(inputName=input_name)).getInputLevels()\n        return lv[0][0] if (lv and lv[0]) else -60.0\n\n    def input_muted(self, input_name):\n        return self._call(requests.GetInputMuted(inputName=input_name)).getInputMuted()\n\n    def switch_scene(self, name):\n        self._call(requests.SetCurrentProgramScene(sceneName=name))\n\n    def _find(self, scene, source):\n        for it in self._call(requests.GetSceneItemList(sceneName=scene)).getSceneItems():\n            if it["sourceName"] == source:\n                return it["sceneItemId"]\n        return None\n\n    def set_visible(self, source, visible, scene=LIVE):\n        iid = self._find(scene, source)\n        if iid is None:\n            return False\n        self._call(requests.SetSceneItemEnabled(\n            sceneName=scene, sceneItemId=iid, sceneItemEnabled=bool(visible)))\n        return True\n\n    def set_transform(self, source, x, y, w, h, scene=LIVE):\n        iid = self._find(scene, source)\n        if iid is None:\n            return False\n        self._call(requests.SetSceneItemTransform(\n            sceneName=scene, sceneItemId=iid,\n            sceneItemTransform={\n                "positionX": float(x), "positionY": float(y),\n                "boundsType": "OBS_BOUNDS_SCALE_INNER", "boundsAlignment": 5,\n                "boundsWidth": float(w), "boundsHeight": float(h),\n            }))\n        return True\n\n    def set_mute(self, input_name, muted):\n        self._call(requests.SetInputMute(inputName=input_name, inputMuted=bool(muted)))\n\n    def apply_layout(self, layout):\n        slots = LAYOUTS[layout]["slots"]\n        for i, src in enumerate(CAM_SOURCES):\n            if i < len(slots):\n                s = slots[i]\n                self.set_transform(src, s["x"], s["y"], s["w"], s["h"])\n                self.set_visible(src, True)\n            else:\n                self.set_visible(src, False)\n\n    def feature_speaker(self, speaker_source):\n        slots = LAYOUTS["autotalk"]["slots"]\n        main, strip = slots[0], slots[1:]\n        self.set_transform(speaker_source, main["x"], main["y"], main["w"], main["h"])\n        self.set_visible(speaker_source, True)\n        others = [s for s in CAM_SOURCES if s != speaker_source]\n        for j, src in enumerate(others):\n            if j < len(strip):\n                s = strip[j]\n                self.set_transform(src, s["x"], s["y"], s["w"], s["h"])\n                self.set_visible(src, True)\n            else:\n                self.set_visible(src, False)\n',
    'server/app.py': '"""Bridge: control hub. Owns OBS, holds live state, drives overlays + dashboard."""\nimport asyncio, json, logging\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI, WebSocket, WebSocketDisconnect, Query\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.responses import JSONResponse\n\nfrom server.config import BRIDGE_HOST, BRIDGE_PORT, CORE_DIR, MOCK_MARKET, CONTROL_TOKEN\nfrom server import mock_market\nfrom server.hub import Hub, LIVE, CAM_SOURCES\nfrom automation.layouts import LAYOUTS\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")\nlog = logging.getLogger("bridge")\n\nhub = Hub()\nSPEAK_THRESHOLD = -30.0\n\nstate = {\n    "layout": "autotalk",\n    "slots": LAYOUTS["autotalk"]["slots"],\n    "mode": "manual",\n    "scene": LIVE,\n    "active_speaker": None,\n    "strip": [],\n    "participants": [\n        {"name": f"CAM {i}", "source": f"CAM-{i}",\n         "mic": "Mic/Aux" if i == 1 else "", "muted": False}\n        for i in range(1, 6)\n    ],\n    "widgets": {"ticker": True, "chart": True, "alerts": True},\n    "canvas": {"w": 1920, "h": 1080},\n    "obs_connected": False,\n}\n\ncontrol_clients: set[WebSocket] = set()\noverlay_clients: set[WebSocket] = set()\n\n\ndef _state_msg():\n    state["obs_connected"] = hub.connected\n    return json.dumps({"type": "state", **state})\n\n\nasync def broadcast_state():\n    msg = _state_msg()\n    for group in (control_clients, overlay_clients):\n        for c in list(group):\n            try:\n                await c.send_text(msg)\n            except Exception:\n                group.discard(c)\n\n\nasync def autotalk_loop():\n    while True:\n        await asyncio.sleep(0.25)\n        if state["mode"] != "auto" or not hub.connected:\n            continue\n        levels = {}\n        for p in state["participants"]:\n            if p["mic"]:\n                try:\n                    levels[p["source"]] = await asyncio.to_thread(hub.audio_level, p["mic"])\n                except Exception:\n                    levels[p["source"]] = -60.0\n        speaking = [p for p in state["participants"]\n                    if levels.get(p["source"], -60.0) > SPEAK_THRESHOLD]\n        if not speaking:\n            continue\n        loudest = max(speaking, key=lambda p: levels[p["source"]])\n        if loudest["name"] != state["active_speaker"]:\n            state["active_speaker"] = loudest["name"]\n            state["strip"] = [p["name"] for p in speaking if p is not loudest][:4]\n            await asyncio.to_thread(hub.feature_speaker, loudest["source"])\n            await broadcast_state()\n\n\nasync def levels_loop():\n    while True:\n        await asyncio.sleep(0.4)\n        if not hub.connected or not control_clients:\n            continue\n        levels = {}\n        for p in state["participants"]:\n            if p["mic"]:\n                try:\n                    levels[p["name"]] = await asyncio.to_thread(hub.audio_level, p["mic"])\n                except Exception:\n                    pass\n        if levels:\n            msg = json.dumps({"type": "levels", "levels": levels})\n            for c in list(control_clients):\n                try:\n                    await c.send_text(msg)\n                except Exception:\n                    control_clients.discard(c)\n\n\n@asynccontextmanager\nasync def lifespan(app):\n    ok = await asyncio.to_thread(hub.connect)\n    if ok:\n        try:\n            state["canvas"] = await asyncio.to_thread(hub.canvas)\n            state["scene"] = await asyncio.to_thread(hub.current_scene)\n            await asyncio.to_thread(hub.apply_layout, state["layout"])\n        except Exception as e:\n            log.warning("initial OBS sync issue: %s", e)\n    else:\n        log.warning("OBS not reachable at boot - dashboard shows OFFLINE; use RECONNECT")\n    t1 = asyncio.create_task(autotalk_loop())\n    t2 = asyncio.create_task(levels_loop())\n    await broadcast_state()\n    log.info("Control token: %s", CONTROL_TOKEN)\n    yield\n    t1.cancel(); t2.cancel()\n    await asyncio.to_thread(hub.disconnect)\n\n\napp = FastAPI(title="smile-live-kit bridge", lifespan=lifespan)\napp.mount("/core", StaticFiles(directory=str(CORE_DIR)), name="core")\n\n\nasync def handle_command(msg: dict):\n    cmd = msg.get("cmd")\n    try:\n        if cmd == "set_layout":\n            layout = msg["layout"]\n            if layout in LAYOUTS:\n                state["layout"] = layout\n                state["slots"] = LAYOUTS[layout]["slots"]\n                if hub.connected:\n                    await asyncio.to_thread(hub.apply_layout, layout)\n        elif cmd == "set_scene":\n            if hub.connected:\n                await asyncio.to_thread(hub.switch_scene, msg["scene"])\n                state["scene"] = msg["scene"]\n        elif cmd == "set_mode":\n            state["mode"] = msg["mode"]\n        elif cmd == "set_speaker":\n            name = msg["name"]\n            part = next((p for p in state["participants"] if p["name"] == name), None)\n            if part:\n                state["mode"] = "manual"\n                state["active_speaker"] = name\n                others = [p["name"] for p in state["participants"] if p["name"] != name]\n                state["strip"] = others[:4]\n                if hub.connected:\n                    await asyncio.to_thread(hub.feature_speaker, part["source"])\n        elif cmd == "toggle_mute":\n            part = next((p for p in state["participants"] if p["name"] == msg["name"]), None)\n            if part and part["mic"] and hub.connected:\n                part["muted"] = not part["muted"]\n                await asyncio.to_thread(hub.set_mute, part["mic"], part["muted"])\n        elif cmd == "toggle_widget":\n            key = msg["widget"]\n            if key in state["widgets"]:\n                state["widgets"][key] = not state["widgets"][key]\n                if hub.connected:\n                    await asyncio.to_thread(hub.set_visible, key, state["widgets"][key])\n        elif cmd == "fire_alert":\n            await broadcast_alert(msg.get("kind", "alert"), msg.get("text", ""))\n        elif cmd == "reconnect_obs":\n            await asyncio.to_thread(hub.disconnect)\n            ok = await asyncio.to_thread(hub.connect)\n            if ok:\n                state["canvas"] = await asyncio.to_thread(hub.canvas)\n                await asyncio.to_thread(hub.apply_layout, state["layout"])\n    except Exception as e:\n        log.error("command %s failed: %s", cmd, e)\n    await broadcast_state()\n\n\nasync def broadcast_alert(kind, text):\n    msg = json.dumps({"type": "alert", "kind": kind, "text": text})\n    for c in list(overlay_clients):\n        try:\n            await c.send_text(msg)\n        except Exception:\n            overlay_clients.discard(c)\n\n\n@app.websocket("/api/control")\nasync def control_ws(ws: WebSocket, token: str = Query("")):\n    if token != CONTROL_TOKEN:\n        await ws.close(code=4001)\n        return\n    await ws.accept()\n    control_clients.add(ws)\n    await ws.send_text(_state_msg())\n    try:\n        while True:\n            await handle_command(json.loads(await ws.receive_text()))\n    except WebSocketDisconnect:\n        control_clients.discard(ws)\n\n\n@app.websocket("/api/autotalk/state")\nasync def overlay_ws(ws: WebSocket):\n    await ws.accept()\n    overlay_clients.add(ws)\n    await ws.send_text(_state_msg())\n    try:\n        while True:\n            await ws.receive_text()\n    except WebSocketDisconnect:\n        overlay_clients.discard(ws)\n\n\n@app.get("/api/market/ticker")\nasync def market_ticker():\n    if MOCK_MARKET:\n        return JSONResponse(mock_market.tick())\n    return JSONResponse({"error": "provider not configured"}, status_code=501)\n\n\n@app.websocket("/api/market/ws")\nasync def market_ws(ws: WebSocket):\n    await ws.accept()\n    try:\n        while True:\n            await ws.send_json(mock_market.tick() if MOCK_MARKET else [])\n            await asyncio.sleep(2)\n    except WebSocketDisconnect:\n        pass\n\n\n@app.post("/api/autotalk/push")\nasync def autotalk_push(payload: dict):\n    state["active_speaker"] = payload.get("main")\n    state["strip"] = payload.get("strip", [])\n    await broadcast_state()\n    return {"ok": True}\n\n\n@app.get("/health")\nasync def health():\n    return {"status": "ok", "obs_connected": hub.connected,\n            "control_clients": len(control_clients), "overlay_clients": len(overlay_clients)}\n\n\nif __name__ == "__main__":\n    import uvicorn\n    uvicorn.run(app, host=BRIDGE_HOST, port=BRIDGE_PORT)\n',
    'core/control.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>SMILE // CONTROL</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Chakra+Petch:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet">\n<style>\n:root{--bg:#0a0f0d;--panel-solid:#101714;--line:#1e2b25;--line-hi:#2c3f36;--ink:#e8f1ec;--dim:#7d918a;--live:#3ddc84;--live-dk:#12351f;--amb:#ffb454;--red:#ff5c5c;--cyan:#5ad1e6;--mono:\'IBM Plex Mono\',ui-monospace,monospace;--disp:\'Chakra Petch\',sans-serif}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml,body{height:100%}\nbody{background:radial-gradient(1200px 600px at 80% -10%,rgba(61,220,132,.06),transparent 60%),radial-gradient(900px 500px at -10% 110%,rgba(90,209,230,.05),transparent 60%),repeating-linear-gradient(0deg,rgba(255,255,255,.015) 0 1px,transparent 1px 3px),var(--bg);color:var(--ink);font-family:var(--mono);overflow-x:hidden}\nbody::after{content:"";position:fixed;inset:0;pointer-events:none;box-shadow:inset 0 0 180px rgba(0,0,0,.55)}\n.wrap{max-width:1240px;margin:0 auto;padding:22px 22px 60px}\nheader{display:flex;align-items:flex-end;gap:18px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:20px}\n.brand{font-family:var(--disp);font-weight:700;font-size:30px;letter-spacing:.04em;line-height:1}\n.brand em{font-style:normal;color:var(--live)}\n.brand small{display:block;font-family:var(--mono);font-weight:400;font-size:11px;color:var(--dim);letter-spacing:.32em;margin-top:6px;text-transform:uppercase}\n.spacer{flex:1}\n.pill{display:inline-flex;align-items:center;gap:8px;font-size:11px;letter-spacing:.14em;text-transform:uppercase;padding:7px 12px;border:1px solid var(--line);border-radius:3px;background:var(--panel-solid);color:var(--dim)}\n.pill .dot{width:8px;height:8px;border-radius:50%;background:#3a4a43}\n.pill.on{color:var(--live);border-color:var(--live-dk)}\n.pill.on .dot{background:var(--live);box-shadow:0 0 10px var(--live);animation:pulse 1.6s infinite}\n.pill.warn{color:var(--amb);border-color:#3d2f1a}.pill.warn .dot{background:var(--amb)}\n@keyframes pulse{50%{opacity:.4}}\n#clock{font-family:var(--disp);font-weight:600;font-size:26px;letter-spacing:.06em;color:var(--ink)}\n.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}\n.panel{grid-column:span 12;border:1px solid var(--line);border-radius:4px;background:var(--panel-solid);position:relative;padding:16px 16px 18px;transition:border-color .25s}\n.panel:hover{border-color:var(--line-hi)}\n.panel::before{content:"";position:absolute;top:-1px;left:-1px;width:14px;height:14px;border-top:2px solid var(--live);border-left:2px solid var(--live);opacity:.7}\n.panel h2{font-family:var(--disp);font-size:12px;font-weight:600;letter-spacing:.3em;text-transform:uppercase;color:var(--dim);margin-bottom:14px;display:flex;align-items:center;gap:10px}\n.panel h2::after{content:"";flex:1;height:1px;background:var(--line)}\n.c4{grid-column:span 4}.c6{grid-column:span 6}.c8{grid-column:span 8}\n@media(max-width:900px){.c4,.c6,.c8{grid-column:span 12}}\n.btn{font-family:var(--disp);font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:12px;color:var(--ink);background:#131c18;border:1px solid var(--line);border-radius:3px;padding:10px 14px;cursor:pointer;transition:all .18s;position:relative}\n.btn:hover{border-color:var(--live);color:var(--live);transform:translateY(-1px);box-shadow:0 4px 14px rgba(61,220,132,.12)}\n.btn:active{transform:translateY(0)}\n.btn.active{background:var(--live-dk);border-color:var(--live);color:var(--live);box-shadow:0 0 0 1px var(--live),0 0 18px rgba(61,220,132,.25)}\n.btn.danger:hover{border-color:var(--red);color:var(--red);box-shadow:0 4px 14px rgba(255,92,92,.15)}\n.row{display:flex;gap:10px;flex-wrap:wrap}\n.layouts{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}\n.layout{display:flex;flex-direction:column;gap:8px;align-items:center;padding:12px 8px}\n.glyph{width:64px;height:36px;border:1px solid var(--line-hi);border-radius:2px;position:relative;background:#0c1210;overflow:hidden}\n.glyph i{position:absolute;background:rgba(61,220,132,.35);border:1px solid rgba(61,220,132,.6)}\n.g-single i{inset:3px}\n.g-duo i{top:3px;bottom:3px;left:3px;width:27px}\n.g-duo i+i{left:auto;right:3px}\n.g-grid4 i{top:3px;left:3px;width:27px;height:13px}\n.g-grid4 i:nth-child(2){left:auto;right:3px}\n.g-grid4 i:nth-child(3){top:auto;bottom:3px}\n.g-grid4 i:nth-child(4){top:auto;bottom:3px;left:auto;right:3px}\n.g-auto i{top:3px;bottom:3px;left:3px;width:38px}\n.g-auto i+i{left:auto;right:3px;width:15px;height:6px}\n.g-auto i:nth-child(3){top:11px}.g-auto i:nth-child(4){top:20px}.g-auto i:nth-child(5){top:29px;height:4px}\n.parts{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}\n@media(max-width:1000px){.parts{grid-template-columns:repeat(2,1fr)}}\n.part{border:1px solid var(--line);border-radius:3px;background:#0d1411;padding:12px;transition:all .2s;position:relative;overflow:hidden}\n.part .nm{font-family:var(--disp);font-weight:600;font-size:14px;letter-spacing:.06em}\n.part .tag{font-size:10px;color:var(--dim);letter-spacing:.18em;text-transform:uppercase;margin-top:2px}\n.part.speaking{border-color:var(--live);box-shadow:0 0 0 1px var(--live),0 0 22px rgba(61,220,132,.28)}\n.part.speaking .tag{color:var(--live)}\n.meter{height:5px;background:#152019;border-radius:2px;margin:10px 0 8px;overflow:hidden}\n.meter b{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--live),var(--amb));transition:width .25s ease}\n.part .ctl{display:flex;gap:6px}\n.part .ctl .btn{flex:1;padding:7px 6px;font-size:10px}\n.btn.muted{border-color:var(--red);color:var(--red)}\n.tgl{display:flex;align-items:center;justify-content:space-between;border:1px solid var(--line);border-radius:3px;padding:10px 12px;background:#0d1411;cursor:pointer;transition:border-color .2s}\n.tgl:hover{border-color:var(--line-hi)}\n.tgl .lbl{font-family:var(--disp);font-size:12px;letter-spacing:.12em;text-transform:uppercase}\n.tgl .sw{width:34px;height:18px;border-radius:10px;background:#1a2620;position:relative;transition:background .2s}\n.tgl .sw::after{content:"";position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#5a6f66;transition:all .2s}\n.tgl.on .sw{background:var(--live-dk)}\n.tgl.on .sw::after{left:18px;background:var(--live);box-shadow:0 0 8px var(--live)}\n.stack{display:flex;flex-direction:column;gap:8px}\ntable{width:100%;border-collapse:collapse;font-size:12px}\nth{font-family:var(--disp);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim);text-align:left;padding:6px 8px;border-bottom:1px solid var(--line)}\ntd{padding:6px 8px;border-bottom:1px solid #141d18;color:var(--ink)}\ntd.num{color:var(--cyan)}\ntd .vis{color:var(--live)} td .hid{color:var(--red)}\ntr:hover td{background:#0e1613}\n#lock{position:fixed;inset:0;background:rgba(6,10,8,.94);display:flex;align-items:center;justify-content:center;z-index:50;backdrop-filter:blur(3px)}\n#lock .box{border:1px solid var(--line-hi);background:var(--panel-solid);padding:34px 36px;border-radius:4px;width:min(400px,90vw);position:relative}\n#lock .box::before{content:"";position:absolute;top:-1px;left:-1px;width:16px;height:16px;border-top:2px solid var(--amb);border-left:2px solid var(--amb)}\n#lock h1{font-family:var(--disp);font-size:20px;letter-spacing:.1em;margin-bottom:6px}\n#lock p{font-size:12px;color:var(--dim);margin-bottom:18px;line-height:1.6}\n#lock input{width:100%;background:#0c1210;border:1px solid var(--line);color:var(--ink);font-family:var(--mono);padding:11px 12px;border-radius:3px;font-size:13px;margin-bottom:12px}\n#lock input:focus{outline:none;border-color:var(--amb)}\n#lock .err{color:var(--red);font-size:11px;margin-top:10px;display:none}\n.hidden{display:none!important}\n#toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%) translateY(20px);background:var(--panel-solid);border:1px solid var(--live);color:var(--live);font-family:var(--disp);font-size:12px;letter-spacing:.12em;text-transform:uppercase;padding:10px 18px;border-radius:3px;opacity:0;transition:all .3s;pointer-events:none;z-index:60}\n#toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n</style>\n</head>\n<body>\n<div id="lock">\n  <div class="box">\n    <h1>CONTROL LOCKED</h1>\n    <p>Enter the control token. It\'s printed in the bridge console at startup (<code>Control token: ...</code>) or set <code>CONTROL_TOKEN</code> in <code>.env</code>.</p>\n    <input id="tok" type="password" placeholder="control token" autocomplete="off">\n    <button class="btn" id="unlock" style="width:100%">UNLOCK</button>\n    <div class="err" id="lockerr">ACCESS DENIED - wrong token</div>\n  </div>\n</div>\n<div class="wrap">\n  <header>\n    <div class="brand">SMILE<em>//</em>CONTROL<small>live kit command centre</small></div>\n    <div class="spacer"></div>\n    <span class="pill" id="obsPill"><span class="dot"></span>OBS <b id="obsTxt">--</b></span>\n    <span class="pill" id="cnvPill"><span class="dot"></span><b id="cnvTxt">--</b></span>\n    <div id="clock">--:--:--</div>\n  </header>\n  <div class="grid">\n    <div class="panel c8">\n      <h2>Layout</h2>\n      <div class="layouts" id="layouts">\n        <button class="btn layout" data-layout="single"><span class="glyph g-single"><i></i></span>SOLO</button>\n        <button class="btn layout" data-layout="duo"><span class="glyph g-duo"><i></i><i></i></span>DUO</button>\n        <button class="btn layout" data-layout="grid4"><span class="glyph g-grid4"><i></i><i></i><i></i><i></i></span>GRID</button>\n        <button class="btn layout" data-layout="autotalk"><span class="glyph g-auto"><i></i><i></i><i></i><i></i><i></i></span>AUTO-TALK</button>\n      </div>\n    </div>\n    <div class="panel c4">\n      <h2>Speaker Mode</h2>\n      <div class="row">\n        <button class="btn" id="modeAuto">AUTO (mic)</button>\n        <button class="btn" id="modeManual">MANUAL</button>\n      </div>\n      <p style="font-size:11px;color:var(--dim);margin-top:12px;line-height:1.6">AUTO promotes the loudest mic. MANUAL: click FEATURE on a participant below.</p>\n    </div>\n    <div class="panel c12">\n      <h2>Participants</h2>\n      <div class="parts" id="parts"></div>\n    </div>\n    <div class="panel c6">\n      <h2>Scenes</h2>\n      <div class="row" id="scenes"></div>\n    </div>\n    <div class="panel c4">\n      <h2>Widgets</h2>\n      <div class="stack" id="widgets"></div>\n    </div>\n    <div class="panel c4">\n      <h2>Alerts</h2>\n      <div class="stack">\n        <button class="btn alert" data-kind="follow">FIRE: FOLLOW</button>\n        <button class="btn alert" data-kind="sub">FIRE: SUB</button>\n        <button class="btn alert" data-kind="donation">FIRE: DONATION</button>\n        <button class="btn alert danger" data-kind="raid">FIRE: RAID</button>\n      </div>\n    </div>\n    <div class="panel c12">\n      <h2>Diagnostics <button class="btn" id="reconnect" style="margin-left:auto;padding:6px 12px;font-size:10px">RECONNECT OBS</button></h2>\n      <table>\n        <thead><tr><th>source</th><th>x</th><th>y</th><th>w</th><th>h</th><th>state</th></tr></thead>\n        <tbody id="diag"></tbody>\n      </table>\n    </div>\n  </div>\n</div>\n<div id="toast"></div>\n<script>\n(function(){\n  var ws=null, S=null;\n  var $=function(s){return document.querySelector(s)};\n  var token=new URLSearchParams(location.search).get(\'token\')||localStorage.getItem(\'ctl_token\')||\'\';\n  function toast(t){var el=$(\'#toast\');el.textContent=t;el.classList.add(\'show\');clearTimeout(el._t);el._t=setTimeout(function(){el.classList.remove(\'show\')},1800)}\n  function pad(n){return String(n).padStart(2,\'0\')}\n  setInterval(function(){var d=new Date();$(\'#clock\').textContent=pad(d.getHours())+\':\'+pad(d.getMinutes())+\':\'+pad(d.getSeconds())},1000);\n  function send(o){if(ws&&ws.readyState===1)ws.send(JSON.stringify(o))}\n  function connect(tok){\n    ws=new WebSocket(\'ws://\'+location.host+\'/api/control?token=\'+encodeURIComponent(tok));\n    ws.onopen=function(){$(\'#lock\').classList.add(\'hidden\');localStorage.setItem(\'ctl_token\',tok);toast(\'LINK ESTABLISHED\')};\n    ws.onmessage=function(e){var m=JSON.parse(e.data);if(m.type===\'state\'){S=m;render(m)}if(m.type===\'levels\'){meters(m.levels)}};\n    ws.onclose=function(ev){if(ev.code===4001){$(\'#lock\').classList.remove(\'hidden\');$(\'#lockerr\').style.display=\'block\'}else setTimeout(function(){connect(tok)},2000)};\n    ws.onerror=function(){ws.close()};\n  }\n  function render(m){\n    $(\'#obsTxt\').textContent=m.obs_connected?\'ONLINE\':\'OFFLINE\';\n    $(\'#obsPill\').className=\'pill \'+(m.obs_connected?\'on\':\'warn\');\n    $(\'#cnvTxt\').textContent=m.canvas.w+\'x\'+m.canvas.h;\n    $(\'#cnvPill\').className=\'pill on\';\n    document.querySelectorAll(\'#layouts .btn\').forEach(function(b){b.classList.toggle(\'active\',b.dataset.layout===m.layout)});\n    $(\'#modeAuto\').classList.toggle(\'active\',m.mode===\'auto\');\n    $(\'#modeManual\').classList.toggle(\'active\',m.mode===\'manual\');\n    var box=$(\'#parts\');box.innerHTML=\'\';\n    m.participants.forEach(function(p){\n      var d=document.createElement(\'div\');d.className=\'part\'+(m.active_speaker===p.name?\' speaking\':\'\');\n      d.innerHTML=\'<div class="nm">\'+p.name+\'</div><div class="tag">\'+(m.active_speaker===p.name?\'ON AIR\':(p.mic?\'mic: \'+p.mic:\'no mic\'))+\'</div><div class="meter"><b data-m="\'+p.name+\'"></b></div><div class="ctl"><button class="btn feat">FEATURE</button>\'+(p.mic?\'<button class="btn mute\'+(p.muted?\' muted\':\'\')+\'">\'+(p.muted?\'UNMUTE\':\'MUTE\')+\'</button>\':\'\')+\'</div>\';\n      d.querySelector(\'.feat\').onclick=function(){send({cmd:\'set_speaker\',name:p.name});toast(p.name+\' featured\')};\n      var mt=d.querySelector(\'.mute\');if(mt)mt.onclick=function(){send({cmd:\'toggle_mute\',name:p.name})};\n      box.appendChild(d)});\n    var sc=$(\'#scenes\');sc.innerHTML=\'\';\n    (m.scenes||[\'01-starting-soon\',\'02-countdown\',\'03-live\',\'04-brb\',\'05-ending\']).forEach(function(n){\n      var b=document.createElement(\'button\');b.className=\'btn\'+(n===m.scene?\' active\':\'\');b.textContent=n.replace(/^\\d+-/,\'\').toUpperCase();\n      b.onclick=function(){send({cmd:\'set_scene\',scene:n});toast(\'scene: \'+n)};sc.appendChild(b)});\n    var wg=$(\'#widgets\');wg.innerHTML=\'\';\n    Object.keys(m.widgets).forEach(function(k){\n      var t=document.createElement(\'div\');t.className=\'tgl\'+(m.widgets[k]?\' on\':\'\');\n      t.innerHTML=\'<span class="lbl">\'+k+\'</span><span class="sw"></span>\';\n      t.onclick=function(){send({cmd:\'toggle_widget\',widget:k})};wg.appendChild(t)});\n    var tb=$(\'#diag\');tb.innerHTML=\'\';\n    (m.diag||[]).forEach(function(r){\n      var tr=document.createElement(\'tr\');\n      tr.innerHTML=\'<td>\'+r.name+\'</td><td class="num">\'+Math.round(r.x)+\'</td><td class="num">\'+Math.round(r.y)+\'</td><td class="num">\'+Math.round(r.w)+\'</td><td class="num">\'+Math.round(r.h)+\'</td><td>\'+(r.visible?\'<span class="vis">VISIBLE</span>\':\'<span class="hid">HIDDEN</span>\')+\'</td>\';\n      tb.appendChild(tr)});\n  }\n  function meters(levels){Object.keys(levels).forEach(function(name){var el=document.querySelector(\'[data-m="\'+name+\'"]\');if(!el)return;var db=levels[name];var pct=Math.max(0,Math.min(100,(db+60)/60*100));el.style.width=pct+\'%\'})}\n  document.querySelectorAll(\'#layouts .btn\').forEach(function(b){b.onclick=function(){send({cmd:\'set_layout\',layout:b.dataset.layout});toast(\'layout: \'+b.dataset.layout)}});\n  $(\'#modeAuto\').onclick=function(){send({cmd:\'set_mode\',mode:\'auto\'});toast(\'AUTO speaker tracking\')};\n  $(\'#modeManual\').onclick=function(){send({cmd:\'set_mode\',mode:\'manual\'});toast(\'MANUAL speaker control\')};\n  document.querySelectorAll(\'.alert\').forEach(function(b){b.onclick=function(){send({cmd:\'fire_alert\',kind:b.dataset.kind,text:b.dataset.kind.toUpperCase()});toast(\'alert fired: \'+b.dataset.kind)}});\n  $(\'#reconnect\').onclick=function(){send({cmd:\'reconnect_obs\'});toast(\'reconnecting OBS...\')};\n  function tryUnlock(){var t=$(\'#tok\').value.trim();if(t)connect(t)}\n  $(\'#unlock\').onclick=tryUnlock;\n  $(\'#tok\').addEventListener(\'keydown\',function(e){if(e.key===\'Enter\')tryUnlock()});\n  if(token){connect(token)}\n})();\n</script>\n</body>\n</html>\n',
    'core/03-live.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=1920, height=1080">\n<title>Live Overlay</title>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nhtml,body{width:1920px;height:1080px;overflow:hidden;background:transparent;font-family:\'Chakra Petch\',\'Segoe UI\',system-ui,sans-serif}\n.frame{position:absolute;border:2px solid rgba(255,255,255,.14);border-radius:6px;pointer-events:none;transition:all .35s ease}\n.frame.on{border-color:rgba(61,220,132,.75);box-shadow:0 0 16px rgba(61,220,132,.28)}\n.frame .label{position:absolute;bottom:10px;left:12px;font-size:15px;font-weight:700;letter-spacing:.08em;color:#fff;background:rgba(6,10,8,.72);padding:4px 12px;border-radius:3px;opacity:0;transition:opacity .3s;text-transform:uppercase}\n.frame.on .label{opacity:1}\n.frame .tag{position:absolute;top:10px;left:12px;font-size:10px;font-weight:700;letter-spacing:.24em;color:#3ddc84;opacity:0;transition:opacity .3s}\n.frame.on .tag{opacity:1;animation:blink 1.4s infinite}\n@keyframes blink{50%{opacity:.35}}\n#alertbox{position:absolute;top:60px;left:50%;transform:translateX(-50%) translateY(-30px);min-width:420px;text-align:center;background:rgba(8,12,10,.9);border:1px solid #3ddc84;border-left:5px solid #3ddc84;border-radius:4px;padding:16px 30px;opacity:0;transition:all .4s cubic-bezier(.2,.9,.3,1.3);pointer-events:none}\n#alertbox.show{opacity:1;transform:translateX(-50%) translateY(0)}\n#alertbox .k{font-size:11px;font-weight:700;letter-spacing:.3em;color:#3ddc84;text-transform:uppercase}\n#alertbox .t{font-size:24px;font-weight:700;color:#fff;margin-top:4px;letter-spacing:.04em}\n</style>\n</head>\n<body>\n<div id="overlay"></div>\n<div id="alertbox"><div class="k" id="ak"></div><div class="t" id="at"></div></div>\n<script>\n(function(){\n  var overlay=document.getElementById(\'overlay\');\n  var currentLayout=null;\n  function buildFrames(slots){\n    overlay.innerHTML=\'\';\n    slots.forEach(function(s,i){\n      var el=document.createElement(\'div\');\n      el.className=\'frame\';el.dataset.slot=s.name;\n      el.style.left=s.x+\'px\';el.style.top=s.y+\'px\';el.style.width=s.w+\'px\';el.style.height=s.h+\'px\';\n      el.innerHTML=\'<span class="tag">ON AIR</span><span class="label"></span>\';\n      overlay.appendChild(el)});\n  }\n  function highlight(state){\n    document.querySelectorAll(\'.frame\').forEach(function(f){f.classList.remove(\'on\');f.querySelector(\'.label\').textContent=\'\'});\n    if(!state.active_speaker)return;\n    var slots=state.slots||[];\n    var mainEl=document.querySelector(\'.frame[data-slot="\'+(slots[0]?slots[0].name:\'main\')+\'"]\');\n    if(mainEl){mainEl.classList.add(\'on\');mainEl.querySelector(\'.label\').textContent=state.active_speaker}\n    (state.strip||[]).forEach(function(nm,i){\n      var slot=slots[i+1];if(!slot)return;\n      var el=document.querySelector(\'.frame[data-slot="\'+slot.name+\'"]\');\n      if(el){el.classList.add(\'on\');el.querySelector(\'.label\').textContent=nm}});\n  }\n  var ab=document.getElementById(\'alertbox\');\n  function showAlert(kind,text){\n    document.getElementById(\'ak\').textContent=kind;\n    document.getElementById(\'at\').textContent=text||kind;\n    ab.classList.add(\'show\');\n    clearTimeout(ab._t);ab._t=setTimeout(function(){ab.classList.remove(\'show\')},4000);\n  }\n  function connect(){\n    var ws=new WebSocket(\'ws://\'+location.host+\'/api/autotalk/state\');\n    ws.onmessage=function(e){\n      var m=JSON.parse(e.data);\n      if(m.type===\'state\'){if(m.layout!==currentLayout&&m.slots){currentLayout=m.layout;buildFrames(m.slots)}highlight(m)}\n      if(m.type===\'alert\'){showAlert(m.kind,m.text)}\n    };\n    ws.onclose=function(){setTimeout(connect,2500)};\n    ws.onerror=function(){ws.close()};\n  }\n  connect();\n})();\n</script>\n</body>\n</html>\n',
}
for p, c in FILES.items():
    pp = pathlib.Path(p)
    pp.parent.mkdir(parents=True, exist_ok=True)
    pp.write_text(c, encoding='utf-8')
    print('wrote', p, len(c.encode('utf-8')), 'bytes')
